const app = document.querySelector('#app');
const {createRound, answer, stats} = QuizCore;
const BANK = window.QUESTION_BANK;
const KEY = 'global-practice-session-v1';
const HISTORY = 'global-practice-history-v1';
let session = null, history = [], view = 'home', filter = 'wrong', storageAvailable = true;
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const duration = ms => { const s=Math.max(0,Math.floor(ms/1000)); return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`; };
const elapsed = () => session ? (session.finishedAt || Date.now()) - session.startedAt : 0;
const sourceHref = q => q.sourceAsset || `sources/${encodeURIComponent(q.source)}.html`;
const sourceLink = q => `<a class="source-link" href="${esc(sourceHref(q))}" target="_blank" rel="noopener">อ่านแหล่งที่มา ↗ ${esc(q.source)}${q.sourcePage?` · หน้า ${q.sourcePage}`:''}</a>${q.verificationUrl?`<a class="source-link" href="${esc(q.verificationUrl)}" target="_blank" rel="noopener">ตรวจสอบกับแหล่งทางการ ↗</a>`:''}`;
const pictureHTML = (q,review=false) => q.image ? `<figure class="question-picture ${review?'review-picture':''}"><button class="picture-button" data-picture="${esc(q.image)}" aria-label="ขยายภาพประกอบคำถาม"><img src="${esc(q.image)}" alt="ภาพบุคคลสำหรับเลือกคำตอบ" ${review?'loading="lazy"':''}><span class="picture-zoom">ขยายภาพ ⤢</span></button><figcaption>ภาพจากเอกสารประกอบ · เลือกชื่อที่ตรงกับภาพ</figcaption></figure>` : '';
function validSession(s) {
  return s && s.version===1 && Array.isArray(s.questions) && s.questions.length===50 && new Set(s.questions.map(q=>q.id)).size===50 && s.questions.every(q=>BANK.some(b=>b.id===q.id) && Array.isArray(q.options) && q.options.length===4 && typeof q.question==='string' && typeof q.explanation==='string' && typeof q.source==='string' && Number.isInteger(q.correct) && q.correct>=0 && q.correct<4) && Array.isArray(s.answers) && s.answers.length===50 && s.answers.every(a=>a===null || Number.isInteger(a)&&a>=0&&a<4) && Number.isInteger(s.index)&&s.index>=0&&s.index<50 && Number.isFinite(s.startedAt) && (!s.finishedAt || Number.isFinite(s.finishedAt)&&s.answers.every(a=>a!==null));
}
try { const saved=JSON.parse(localStorage.getItem(KEY)); if(validSession(saved))session=saved; const h=JSON.parse(localStorage.getItem(HISTORY)); if(Array.isArray(h))history=h.filter(r=>Number.isFinite(r.date)&&Number.isInteger(r.correct)&&r.correct>=0&&r.correct<=50&&Number.isFinite(r.elapsed)).slice(0,8); } catch(e) { storageAvailable=false; }
function persist() { try { localStorage.setItem(KEY,JSON.stringify(session));localStorage.setItem(HISTORY,JSON.stringify(history)); }catch(e){storageAvailable=false;} }
const warning = () => storageAvailable ? '' : '<p class="storage-warning">เบราว์เซอร์นี้ไม่สามารถบันทึกความคืบหน้าได้ กรุณาทำรอบนี้ให้จบก่อนปิดหน้าเว็บ</p>';
const globe = `<svg viewBox="0 0 300 300" fill="none" aria-hidden="true"><circle cx="150" cy="150" r="119" fill="#dce7cd" stroke="#729066" stroke-width="1.2"/><ellipse cx="150" cy="150" rx="75" ry="119" stroke="#a6b999"/><ellipse cx="150" cy="150" rx="31" ry="119" stroke="#a6b999"/><ellipse cx="150" cy="150" rx="119" ry="42" stroke="#a6b999"/><path d="M43 99H257M43 201H257M31 150H269M150 31V269" stroke="#a6b999"/><path d="M61 79L78 65 103 61 121 77 114 93 93 97 91 113 109 128 103 151 85 160 72 138 52 132 43 111ZM104 158L125 165 141 186 132 215 120 230 112 253 101 234 95 211 89 190ZM162 57L189 51 211 70 235 77 245 98 230 111 211 107 202 130 180 120 169 98 150 92 155 74ZM149 126L168 118 191 137 200 159 183 194 172 204 155 183 143 155ZM199 137L211 146 219 167 210 176 202 159ZM220 203L241 192 255 206 248 223 231 230 219 219Z" fill="#7e9c6e" opacity=".8"/><circle cx="212" cy="145" r="6" fill="#db7045" stroke="#fff" stroke-width="3"/><circle cx="212" cy="145" r="15" stroke="#db7045" opacity=".4"/><path d="M18 181C35 222 173 242 265 113" stroke="#db7045" stroke-width="1.4" stroke-dasharray="4 5"/><circle cx="265" cy="113" r="3" fill="#db7045"/></svg>`;
function renderHome() {
  view='home';
  const categories=[...new Set(BANK.map(q=>q.category))], icons=['◈','◎','↗','▧','♧'];
  app.innerHTML = `${warning()}<section class="hero"><div class="hero-copy"><div class="eyebrow">YOUR WORLD. YOUR KNOWLEDGE.</div><h1>เปิดโลกความรู้<br>พร้อมสู่<span style="color:var(--green)">สนามสอบ.</span></h1><p>ฝึกข้อสอบภาษาอังกฤษ เน้นไฟล์ Global EE Exam<br>เรียนรู้จากทุกคำตอบ ด้วยคำอธิบายภาษาไทยที่เข้าใจง่าย</p><div class="hero-actions"><button class="btn primary" data-action="start">เริ่มฝึก 50 ข้อ <span>↗</span></button>${session&&!session.finishedAt?'<button class="btn secondary" data-action="resume">ทำต่อจากครั้งก่อน →</button>':''}${session&&session.finishedAt?'<button class="btn secondary" data-action="results">ดูผลรอบล่าสุด</button>':''}</div><p class="small-note">สุ่ม Global EE Exam 25–40 ข้อต่อรอบ · ไม่มีเวลาจำกัด</p></div><div class="globe-card"><span class="globe-label">EXPLORE · LEARN · REPEAT</span>${globe}<div class="float-note float-one"><span class="note-symbol">✓</span><span><b>เรียนรู้ทันที</b>เฉลยพร้อมคำอธิบายไทย</span></div><div class="float-note float-two"><span class="note-symbol">↻</span><span><b>50 questions</b>รอบใหม่ ความท้าทายใหม่</span></div><span class="globe-coordinates">13.7563° N / 100.5018° E</span></div></section><section class="metrics" aria-label="รูปแบบข้อสอบ"><div class="metric"><strong>${BANK.length}</strong><div><p>ข้อในคลังคำถาม</p><small>เรียบเรียงจากสไลด์ใน Data</small></div></div><div class="metric"><strong>50</strong><div><p>ข้อในแต่ละรอบ</p><small>25–40 ข้อหลัก · รูปภาพ 5 ข้อ</small></div></div><div class="metric"><strong>4</strong><div><p>ตัวเลือกภาษาอังกฤษ</p><small>กดตอบแล้วดูเฉลยได้ทันที</small></div></div></section><section><div class="section-title"><h2>ทุกเรื่องที่ควรรู้ รอบโลก</h2><span>5 หมวดความรู้ · รวมคำถามรูปภาพ</span></div><div class="topics">${categories.map((c,i)=>`<div class="topic"><div class="topic-icon" aria-hidden="true">${icons[i]}</div><h3>${esc(c)}</h3><small>${BANK.filter(q=>q.category===c).length} คำถาม</small></div>`).join('')}</div></section><div class="bottom-panels"><section class="how"><h3>เริ่มได้ใน 3 ขั้นตอน</h3><div class="steps"><div class="step"><span class="step-number">01</span><b>เริ่มรอบใหม่</b>สุ่ม 25–40 ข้อจาก Global EE Exam</div><div class="step"><span class="step-number">02</span><b>ตอบและทำความเข้าใจ</b>อ่านเฉลยหลังเลือกตอบ</div><div class="step"><span class="step-number">03</span><b>ทบทวนแล้วลองอีกครั้ง</b>ดูคะแนนและข้อที่ตอบผิด</div></div></section><section class="history"><h3>ประวัติการฝึกของคุณ <span style="font-size:10px;color:var(--muted);font-weight:400">บนเบราว์เซอร์นี้</span></h3>${history.length?history.slice(0,3).map(r=>`<div class="history-row"><span>${new Date(r.date).toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'numeric'})} · ${duration(r.elapsed)} นาที</span><strong>${r.correct}<span style="font-size:11px;color:var(--muted)"> / 50</span></strong></div>`).join(''):'<p class="history-empty">ก้าวแรกเริ่มจากรอบแรกของคุณ<br>เมื่อทำครบ 50 ข้อ คะแนนจะปรากฏที่นี่</p>'}</section></div><details class="sources"><summary>เกี่ยวกับคำถามและเอกสารที่ใช้</summary><p>ใช้ Global EE Exam เป็นไฟล์หลัก โดยมี ${BANK.filter(q=>q.primary).length} ข้อจากไฟล์นี้ในคลัง รอบใหม่สุ่มจำนวนข้อจากไฟล์หลักระหว่าง 25–40 ข้อ มีข้อรูปภาพ 5 ข้อ และใช้เนื้อหาเสริมเติมให้ครบ 50 ข้อ คำถามเรียบเรียงจาก PDF ใน Data/Global และภาพสรุปใน Data โดยเลือกหัวข้อที่อ่านได้ชัดเจนและมีคำตอบเดียว ข้อที่เกี่ยวข้องกับเหตุการณ์หรือบุคคลระบุช่วงเวลาในคำถาม ไม่ได้อ้างว่าเป็นข่าวล่าสุด มีคำถามระบุบุคคลจากภาพใน PDF หน้าที่ 32–35 โดยใช้ชื่อกำกับในเอกสารเป็นเฉลย มีเนื้อหาเสริมจากภาพสรุปแร่ ขยะพลาสติก โนเบล 2025 มรดกโลก 2025 ปัจจัยราคาทองคำ เสรีภาพอินเทอร์เน็ต และเรือดำน้ำนิวเคลียร์ พร้อมลิงก์อ่านสไลด์ต้นฉบับหลังตอบ ข้อที่ถามอันดับหรือตัวเลขระบุปีหรืออ้างข้อมูลตามสไลด์</p><p>เอกสารต้นฉบับบางส่วนมีข้อมูลเก่าหรือข้อความขัดแย้ง จึงไม่นำข้อกำกวม เช่น จำนวนสมาชิกปัจจุบัน ผู้นำปัจจุบัน หรือข้อที่ต้องดูภาพที่ขาดหายหรือไม่มีชื่อกำกับ มาใช้เป็นคำถาม คะแนนใช้สำหรับฝึกทบทวน</p>${[...new Map(BANK.map(q=>[q.source,q])).values()].map(q=>`<a href="${esc(sourceHref(q))}" target="_blank" rel="noopener">↗ ${esc(q.source)}</a>`).join('')}</details>`;
}
function renderQuiz(focus=false) {
  view='quiz'; const q=session.questions[session.index], chosen=session.answers[session.index], answered=chosen!==null, st=stats(session);
  app.innerHTML=`${warning()}<div class="quiz-heading"><div><span class="round-label">${['ee-range-v1','ee-main-v1'].includes(session.mode)?`GLOBAL EE EXAM · ${session.questions.filter(item=>item.primary).length} MAIN + ${session.questions.filter(item=>!item.primary&&!item.image).length} EXTRA + ${session.questions.filter(item=>item.image).length} PICTURES`:'PRACTICE SESSION / 50 QUESTIONS'}</span><h1>ทีละข้อ ไปได้ไกลกว่าเดิม</h1></div><button class="quiet" data-action="home">← พักไว้ก่อน</button></div><div class="quiz-layout"><section class="question-panel"><div class="question-top"><span>QUESTION ${String(session.index+1).padStart(2,'0')} <span style="color:#bcc7bd">/ 50</span></span><span class="category-badge">${esc(q.category)}</span></div><h2 id="question-title" lang="en" tabindex="-1">${esc(q.question)}</h2>${pictureHTML(q)}<div class="option-list">${q.options.map((o,i)=>`<button class="option ${answered&&i===q.correct?'correct':''} ${answered&&i===chosen&&i!==q.correct?'wrong':''}" data-choice="${i}" ${answered?'disabled':''} aria-label="${'ABCD'[i]}. ${esc(o)}${answered&&i===q.correct?' — คำตอบที่ถูกต้อง':''}${answered&&i===chosen?' — คำตอบของคุณ':''}"><span class="letter">${'ABCD'[i]}</span><span class="option-text" lang="en">${esc(o)}</span>${answered&&i===q.correct?'<span class="answer-mark">✓</span>':answered&&i===chosen?'<span class="answer-mark">✕</span>':''}</button>`).join('')}</div><div aria-live="polite">${answered?`<div class="explanation ${chosen!==q.correct?'is-wrong':''}"><h3>${chosen===q.correct?'✓ ตอบถูก เก่งมาก!':'เรียนรู้อีกนิด แล้วไปต่อ'} · เฉลย ${'ABCD'[q.correct]}</h3><p>${esc(q.explanation)}</p>${sourceLink(q)}</div>`:''}</div><div class="question-nav"><button class="btn secondary" data-action="previous" ${session.index===0?'disabled':''}>← ข้อก่อนหน้า</button>${st.answered===50?'<button class="btn primary" data-action="finish">ดูสรุปคะแนน ↗</button>':`<button class="btn primary" data-action="next">${session.index===49?'ไปข้อที่ยังไม่ตอบ':answered?'ข้อถัดไป':'ข้ามข้อนี้'} →</button>`}</div><p class="keyboard-hint">เลือกคำตอบด้วยปุ่ม 1–4 · เปลี่ยนข้อด้วยปุ่ม ← →</p></section><aside><section class="side-card"><h3>ความคืบหน้าของคุณ</h3><div class="progress-stats"><span>ตอบแล้ว <b>${st.answered}</b> / 50</span><span class="time" id="timer">${duration(elapsed())}</span></div><div class="progress"><div style="width:${st.answered*2}%"></div></div><div class="score-strip"><span>ตอบถูก</span><strong>${st.correct} ข้อ</strong></div><nav class="question-grid" aria-label="เลือกข้อสอบ">${session.questions.map((item,i)=>`<button class="question-number ${i===session.index?'current':''} ${session.answers[i]!==null?(session.answers[i]===item.correct?'ok':'bad'):''}" data-index="${i}" ${i===session.index?'aria-current="step"':''} aria-label="ข้อ ${i+1} ${session.answers[i]===null?'ยังไม่ตอบ':session.answers[i]===item.correct?'ตอบถูก':'ตอบผิด'}">${i+1}</button>`).join('')}</nav><div class="legend"><span>ถูก</span><span>ผิด</span><span>ยังไม่ตอบ</span></div></section><p class="side-note">${session.mode!=='ee-range-v1'?'รอบนี้เริ่มก่อนอัปเดต สัดส่วนเดิมยังคงไว้ เริ่มรอบใหม่เพื่อสุ่ม Global EE Exam 25–40 ข้อ<br>':''}เลือกเลขข้อเพื่อย้อนดูหรือข้ามไปข้ออื่นได้<br>เมื่อเลือกคำตอบแล้วจะเปลี่ยนไม่ได้<br>${storageAvailable?'บันทึกให้อัตโนมัติ กลับมาทำต่อได้ทุกเมื่อ':'ทำให้ครบก่อนปิดหน้าเว็บเพื่อเก็บคะแนนรอบนี้'}</p></aside></div>`;
  if(focus)document.querySelector('#question-title').focus({preventScroll:true});
}
function renderResult() {
  view='result'; const st=stats(session), list=session.questions.map((q,i)=>({q,i})).filter(({q,i})=>filter==='all'||session.answers[i]!==q.correct);
  app.innerHTML=`${warning()}<section class="result-hero"><div class="eyebrow">PRACTICE COMPLETE</div><h1>${st.correct>=40?'เยี่ยมเลย โลกกว้างอยู่ในมือคุณ':st.correct>=25?'ก้าวหน้าไปอีกขั้นแล้ว':'ทุกข้อคือโอกาสเรียนรู้'}</h1><p style="color:var(--muted)">ครบ 50 ข้อแล้ว ทบทวนอีกนิดเพื่อพร้อมในรอบถัดไป</p><div class="score-ring" style="--score:${st.correct*2}%"><div class="score-inner"><strong>${st.correct}</strong><span>คะแนนจาก 50 ข้อ</span></div></div><div class="result-summary"><span>ความแม่นยำ <b>${st.correct*2}%</b></span><span>ตอบผิด <b>${50-st.correct} ข้อ</b></span><span>เวลา <b>${duration(elapsed())}</b></span></div><div class="result-actions"><button class="btn primary" data-action="start">สุ่ม 50 ข้อชุดใหม่ ↻</button><button class="btn secondary" data-action="home">กลับหน้าแรก</button></div></section><section><div class="review-title"><h2>ทบทวนให้เข้าใจมากขึ้น</h2><div class="tabs" role="group" aria-label="เลือกข้อที่ต้องการทบทวน"><button class="${filter==='wrong'?'active':''}" data-filter="wrong" aria-pressed="${filter==='wrong'}">ข้อที่ตอบผิด (${50-st.correct})</button><button class="${filter==='all'?'active':''}" data-filter="all" aria-pressed="${filter==='all'}">ทุกข้อ (50)</button></div></div>${list.length?list.map(({q,i})=>`<article class="review-card"><div class="question-top" style="margin:0"><span>ข้อ ${i+1} · ${esc(q.category)}</span><span class="${session.answers[i]===q.correct?'badge-ok':'badge-bad'}">${session.answers[i]===q.correct?'✓ ถูก':'✕ ผิด'}</span></div><h3 lang="en">${esc(q.question)}</h3>${pictureHTML(q,true)}<p class="review-answer ${session.answers[i]!==q.correct?'wrong-text':''}">คุณตอบ: <span lang="en">${'ABCD'[session.answers[i]]}. ${esc(q.options[session.answers[i]])}</span></p><p class="review-answer badge-ok">คำตอบที่ถูก: <span lang="en">${'ABCD'[q.correct]}. ${esc(q.options[q.correct])}</span></p><div class="explanation"><p>${esc(q.explanation)}</p>${sourceLink(q)}</div></article>`).join(''):'<div class="empty-review">✓ ตอบถูกครบทุกข้อ! ลองสุ่มรอบใหม่เพื่อฝึกต่อได้เลย</div>'}</section>`;
}
function start() {
  if(session&&!session.finishedAt&&!confirm('มีรอบที่ยังทำไม่ครบ ต้องการเริ่มชุดใหม่และแทนที่ความคืบหน้าเดิมหรือไม่?'))return;
  session={version:1,mode:'ee-range-v1',questions:createRound(BANK),answers:Array(50).fill(null),index:0,startedAt:Date.now(),finishedAt:null};persist();renderQuiz();window.scrollTo(0,0);
}
function go(index) {session.index=index;persist();renderQuiz(true);window.scrollTo(0,0);}
function finish() {
  if(stats(session).answered!==50)return;
  if(!session.finishedAt){session.finishedAt=Date.now();history.unshift({date:session.finishedAt,correct:stats(session).correct,elapsed:elapsed()});history=history.slice(0,8);persist();}filter='wrong';renderResult();window.scrollTo(0,0);
}
app.addEventListener('click', e=>{
  const b=e.target.closest('button');if(!b||b.disabled)return;
  if(b.dataset.picture){openPicture(b.dataset.picture);return;}
  if(b.dataset.choice!==undefined&&view==='quiz'){if(answer(session,session.index,Number(b.dataset.choice))){persist();renderQuiz();const next=app.querySelector('[data-action="next"], [data-action="finish"]');next?.focus({preventScroll:true});}return;}
  if(b.dataset.index!==undefined&&view==='quiz'){go(Number(b.dataset.index));return;}
  if(b.dataset.filter){filter=b.dataset.filter;renderResult();app.querySelector(`[data-filter="${filter}"]`)?.focus({preventScroll:true});return;}
  switch(b.dataset.action){case 'start':start();break;case 'home':renderHome();window.scrollTo(0,0);break;case 'resume':renderQuiz();break;case 'results':filter='wrong';renderResult();break;case 'previous':if(session.index>0)go(session.index-1);break;case 'next':go(session.index<49?session.index+1:session.answers.findIndex(a=>a===null));break;case 'finish':finish();break;}
});
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();renderHome();window.scrollTo(0,0);});
document.addEventListener('keydown',e=>{
  if(pictureDialog.open||view!=='quiz'||e.ctrlKey||e.altKey||e.metaKey||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;
  if(/^[1-4]$/.test(e.key)){e.preventDefault();app.querySelector(`[data-choice="${Number(e.key)-1}"]`)?.click();}
  if(e.key==='ArrowRight'){e.preventDefault();app.querySelector('[data-action="next"]')?.click();}
  if(e.key==='ArrowLeft'){e.preventDefault();app.querySelector('[data-action="previous"]')?.click();}
});
setInterval(()=>{const timer=document.querySelector('#timer');if(timer)timer.textContent=duration(elapsed());},1000);
const pictureDialog=document.querySelector('#picture-dialog');
function openPicture(src){
  document.querySelector('#enlarged-picture').src=src;
  pictureDialog.showModal();
}
document.querySelector('#close-picture').addEventListener('click',()=>pictureDialog.close());
pictureDialog.addEventListener('click',e=>{if(e.target===pictureDialog){const r=pictureDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)pictureDialog.close();}});
app.addEventListener('error',e=>{if(e.target.tagName==='IMG'){const figure=e.target.closest('figure');if(figure){figure.querySelector('figcaption').textContent='โหลดภาพไม่สำเร็จ กรุณารีโหลดหน้าเว็บ หรือข้ามไปข้ออื่นก่อน';}}},true);
renderHome();

